do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: The Pastoral Letters and Philemon$j$, $j${"questions": [{"q": "Why are the letters to Timothy and Titus called the pastoral letters?", "options": ["They were written to farmers", "They were written to Jewish priests", "They were written to young leaders who cared for churches", "They were written to Roman officials"]}, {"q": "According to 1 Timothy 4:12, what was Timothy to be?", "options": ["A ruler over the church", "A silent observer", "A tax collector", "An example of the believers"]}, {"q": "According to 2 Timothy 3:16, all scripture is given by what?", "options": ["Tradition", "The elders of Israel", "Roman law", "Inspiration of God"]}, {"q": "What did Paul ask Philemon to do about Onesimus?", "options": ["Receive him as a brother beloved", "Punish him", "Sell him", "Send him away"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Pastoral Letters and Philemon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,0}'::int[], array[$j$Paul wrote them to Timothy and Titus, who were caring for churches.$j$,$j$Paul told Timothy to be an example of the believers.$j$,$j$All scripture is given by inspiration of God.$j$,$j$Paul asked Philemon to receive Onesimus as a brother beloved.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Pastoral Letters and Philemon$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$, $j${"questions": [{"q": "Why are Ephesians, Philippians, Colossians and Philemon called the prison letters?", "options": ["They were found in a prison", "Paul wrote them while he was in prison", "They were written to prisoners", "They are about a jailer"]}, {"q": "What does Ephesians 6:17 call the sword of the Spirit?", "options": ["The church", "Fasting", "The law", "The word of God"]}, {"q": "Which letter is known as the letter of joy?", "options": ["Colossians", "Titus", "Philippians", "Philemon"]}, {"q": "What hope did Paul give the Thessalonians in 1 Thessalonians 4?", "options": ["That persecution would end tomorrow", "That the church would become rich", "That the dead in Christ shall rise and we shall ever be with the Lord", "That the law would be restored"]}, {"q": "What did Paul say in 2 Timothy 4:7 at the end of his life?", "options": ["I have built a great church", "I have escaped prison", "I have fought a good fight, I have finished my course, I have kept the faith", "I have finished the temple"]}, {"q": "What did Paul ask Philemon to do in his short letter?", "options": ["Send money to Jerusalem", "Receive Onesimus as a brother", "Close the church at Colossae", "Come to Rome"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2,2,1}'::int[], array[$j$Paul wrote these four letters from prison.$j$,$j$The sword of the Spirit is the word of God.$j$,$j$Philippians is full of joy and rejoicing.$j$,$j$Paul comforted the church with the promise of the Lord's return.$j$,$j$Paul looked back on his life and said he had kept the faith.$j$,$j$Paul asked Philemon to receive Onesimus back as a brother beloved.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Paul's Letters, Part Two, Ephesians to Philemon$j$ on conflict (item_id) do nothing;
end
$seed$;
